ssh ws2 'D=/home/jeff/project/65_final_0723; cd $D
echo "=== aggregate quality over all successful meshes ==="
grep -h "^\[MESH\]" mesh_logs/*.log | awk "{
  for(i=1;i<=NF;i++){
    if(\$i ~ /^n_tet=/){gsub(/n_tet=|,/,\"\",\$i); t+=\$i; n++; if(\$i>tmax)tmax=\$i; if(tmin==0||\$i<tmin)tmin=\$i}
    if(\$i ~ /^min_q=/){gsub(/min_q=/,\"\",\$i); q+=\$i; if(qmin==0||\$i<qmin)qmin=\$i; if(\$i>qmax)qmax=\$i}
    if(\$i ~ /^mean_q=/){gsub(/mean_q=/,\"\",\$i); m+=\$i}
    if(\$i ~ /^neg=/){gsub(/neg=/,\"\",\$i); neg+=\$i}
  }
} END {
  printf \"meshes logged : %d\n\", n
  printf \"n_tet         : min %d  mean %d  max %d\n\", tmin, t/n, tmax
  printf \"min_q         : worst %.4f  mean %.4f  best %.4f\n\", qmin, q/n, qmax
  printf \"mean_q        : %.4f\n\", m/n
  printf \"negative Jac  : %d\n\", neg
}"
echo "=== algo used ==="; grep -h "^\[MESH\]" mesh_logs/*.log | grep -o "algo=[A-Za-z]*" | sort | uniq -c'

ssh ws2 'D=/home/jeff/project/65_final_0723; cd $D
grep -h "^\[MESH\]" mesh_logs/*.log | sed "s/,//g" | awk "{
  for(i=1;i<=NF;i++){
    if(\$i ~ /^n_tet=/){sub(/n_tet=/,\"\",\$i); v=\$i+0; t+=v; n++; if(v>tmax)tmax=v; if(tmin==0||v<tmin)tmin=v}
    if(\$i ~ /^min_q=/){sub(/min_q=/,\"\",\$i); q=\$i+0}
